.minimbasim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2a26;
    background: linear-gradient(180deg, #f3eee2 0%, #efe7d4 100%);
    border-radius: 18px;
}

.minimbasim-container * {
    box-sizing: border-box;
}

.minimbasim-header {
    text-align: center;
    padding: 30px 22px 24px;
    background: linear-gradient(135deg, #14233f 0%, #1d3a5f 60%, #20486b 100%);
    color: #f6efdc;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0f1c33;
    border-bottom: 4px solid #c9a227;
    box-shadow: 0 12px 30px rgba(20, 35, 63, 0.32);
}

.minimbasim-header h1 {
    margin: 10px 0 12px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.5rem;
    font-weight: 700;
    letter-spacing: -0.4px;
    color: #f8f2df;
}

.minimbasim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #e6c659;
    background: rgba(201, 162, 39, 0.14);
    border: 1px solid rgba(201, 162, 39, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.minimbasim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #d9e0ec;
}

.minimbasim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a5547;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.minimbasim-period-counter #currentDay,
.minimbasim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1d3a5f;
}

.minimbasim-round-name {
    background: #1d3a5f;
    color: #f6efdc;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.minimbasim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: rgba(201, 162, 39, 0.18);
    border: 1px solid rgba(201, 162, 39, 0.45);
    padding: 4px 12px;
    border-radius: 999px;
}

.minimbasim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.minimbasim-status-card {
    background: #fcfaf3;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd2b8;
    box-shadow: 0 6px 16px rgba(20, 35, 63, 0.10);
    border-top: 4px solid #1d3a5f;
}

.minimbasim-card-enroll { border-top-color: #1d3a5f; }
.minimbasim-card-contrib { border-top-color: #2e7d52; }
.minimbasim-card-diff { border-top-color: #c9a227; }
.minimbasim-card-reach { border-top-color: #7a4ea8; }

.minimbasim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #7a7361;
}

.minimbasim-value {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.6rem;
    font-weight: 700;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1d3a5f;
    font-variant-numeric: tabular-nums;
}

.minimbasim-card-enroll .minimbasim-value { color: #1d3a5f; }
.minimbasim-card-contrib .minimbasim-value { color: #2e7d52; }
.minimbasim-card-diff .minimbasim-value { color: #a6831a; }
.minimbasim-card-reach .minimbasim-value { color: #7a4ea8; }

.minimbasim-sublabel {
    font-size: 0.75rem;
    color: #8a8472;
    line-height: 1.35;
}

.minimbasim-enroll-hit { border-top-color: #2e7d52; }
.minimbasim-enroll-hit .minimbasim-value { color: #2e7d52; }
.minimbasim-enroll-miss .minimbasim-value { color: #b3471f; }

.minimbasim-contrib-positive .minimbasim-value { color: #2e7d52; }
.minimbasim-contrib-negative .minimbasim-value { color: #b3471f; }
.minimbasim-contrib-hit { border-top-color: #2e7d52; }

.minimbasim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fcfaf3;
    border: 1px solid #ddd2b8;
    color: #4a4534;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.minimbasim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #8a5a12;
}

.minimbasim-briefing {
    display: flex;
    gap: 14px;
    background: #fcfaf3;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 35, 63, 0.08);
}

.minimbasim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.minimbasim-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 1.16rem;
    color: #1d3a5f;
    margin-bottom: 6px;
}

.minimbasim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #423d30;
}

.minimbasim-briefing-text strong { color: #1d3a5f; }
.minimbasim-briefing-text em { color: #8a5a12; font-style: italic; }

.minimbasim-controls {
    background: #fcfaf3;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd2b8;
    box-shadow: 0 6px 16px rgba(20, 35, 63, 0.08);
}

.minimbasim-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.2rem;
    font-weight: 700;
    color: #1d3a5f;
    border-bottom: 2px solid #e3d9bf;
    padding-bottom: 8px;
}

.minimbasim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2e2a20;
    margin: 14px 0 6px;
}

.minimbasim-container select,
.minimbasim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c7bb9c;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2b2a26;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.minimbasim-container select:focus,
.minimbasim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a227;
    box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.22);
}

.minimbasim-container select option {
    background-color: #ffffff;
    color: #2b2a26;
}

.minimbasim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1d3a5f;
}

.minimbasim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a5547;
    margin-top: 4px;
}

.minimbasim-range-readout span:nth-child(2) {
    color: #1d3a5f;
    font-weight: 800;
}

.minimbasim-hint {
    font-size: 0.8rem;
    color: #8a8472;
    margin-top: 4px;
    line-height: 1.45;
}

.minimbasim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.minimbasim-container .btn-primary {
    background: linear-gradient(135deg, #1d3a5f 0%, #2a5688 100%);
    border: none;
    color: #f6efdc;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(29, 58, 95, 0.32);
    letter-spacing: 0.3px;
}

.minimbasim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.minimbasim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c7bb9c;
    color: #6a6453;
    background: transparent;
}

.minimbasim-coach {
    background: linear-gradient(135deg, #14233f 0%, #1d3a5f 100%);
    color: #e9eef6;
    border: 1px solid #0f1c33;
    border-left: 5px solid #c9a227;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.24);
}

.minimbasim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e6c659;
    margin-bottom: 8px;
}

.minimbasim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.minimbasim-coach-body strong { color: #e6c659; }
.minimbasim-coach-body em { color: #f1d98a; font-style: italic; }

.minimbasim-history,
.minimbasim-chart {
    background: #fcfaf3;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd2b8;
    box-shadow: 0 6px 16px rgba(20, 35, 63, 0.08);
}

.minimbasim-history h3,
.minimbasim-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.14rem;
    font-weight: 700;
    color: #1d3a5f;
}

.minimbasim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #423d30;
}

.minimbasim-container table#usfHistoryTable th {
    background: #1d3a5f;
    color: #f6efdc;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #14233f;
}

.minimbasim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e3d9bf;
    color: #423d30;
}

.minimbasim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f5efdf;
}

.minimbasim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .minimbasim-container {
        padding: 14px;
    }
    .minimbasim-header h1 {
        font-size: 1.8rem;
    }
    .minimbasim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .minimbasim-value {
        font-size: 2.1rem;
    }
    .minimbasim-clock {
        margin-left: 0;
    }
    .minimbasim-period-counter {
        font-size: 0.88rem;
    }
    .minimbasim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .minimbasim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   v1.1.0 — Completion debrief (append-only, scoped .mmba-cm)
   Palette: navy #1d3a5f · gold #c9a227 · purple #7a4ea8
   ============================================================ */
.mmba-cm { font-family: inherit; color: #2b2b2b; text-align: left; }
.mmba-cm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    border-bottom: 3px solid #c9a227; padding-bottom: 14px; margin-bottom: 16px; }
.mmba-cm-scorebox { display: flex; flex-direction: column; align-items: center;
    background: #1d3a5f; color: #fff; border-radius: 12px; padding: 12px 20px; min-width: 130px; }
.mmba-cm-score { font-size: 2.6rem; line-height: 1; font-weight: 800; }
.mmba-cm-score-max { font-size: 1rem; font-weight: 600; opacity: 0.75; margin-left: 2px; }
.mmba-cm-score-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em;
    opacity: 0.85; margin-top: 4px; }
.mmba-cm-tier { font-size: 1.5rem; font-weight: 700; color: #1d3a5f; flex: 1 1 auto; }
.mmba-cm-targets { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; }
.mmba-cm-target { flex: 1 1 220px; display: flex; align-items: center; gap: 10px;
    background: #f6f4ec; border: 1px solid #e4dfce; border-left: 5px solid #8a8472;
    border-radius: 8px; padding: 10px 14px; }
.mmba-cm-target.is-met { border-left-color: #2e7d4f; }
.mmba-cm-target.is-missed { border-left-color: #b4442e; }
.mmba-cm-target-label { font-weight: 600; color: #3a3a3a; }
.mmba-cm-target-val { margin-left: auto; font-variant-numeric: tabular-nums; font-weight: 700; color: #1d3a5f; }
.mmba-cm-badge { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;
    padding: 3px 9px; border-radius: 999px; color: #fff; }
.mmba-cm-badge.is-met { background: #2e7d4f; }
.mmba-cm-badge.is-missed { background: #b4442e; }
.mmba-cm-kpis { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.mmba-cm-kpi { flex: 1 1 120px; text-align: center; background: #fff; border: 1px solid #e4dfce;
    border-top: 3px solid #7a4ea8; border-radius: 8px; padding: 10px 8px; }
.mmba-cm-kpi-v { font-size: 1.35rem; font-weight: 800; color: #1d3a5f; font-variant-numeric: tabular-nums; }
.mmba-cm-kpi-l { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.04em; color: #6b6656; margin-top: 3px; }
.mmba-cm-insights-title { font-weight: 700; color: #1d3a5f; margin-bottom: 6px; }
.mmba-cm-insights ul { margin: 0; padding-left: 20px; }
.mmba-cm-insights li { margin-bottom: 7px; line-height: 1.5; }

