(function() {
    'use strict';

    class MiniMBAAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Build the Mini-MBA`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Eastbrook Office of Executive Education, USD).
            this.TARGET_ENROLL = 300;          // fixed institutional enrollment target
            this.TARGET_CONTRIB = 1.5;         // USD 1.5M binding contribution to the provost
            this.OVERHEAD = 0.28;              // 28% institutional overhead on program revenue
            this.RIVAL_PRICE = 1900;           // LearnLadder online anchor price (USD)
            this.LEGACY_PRICE = 9500;          // legacy Management Certificate price (USD)
            this.PRESPRING = 165;              // confirmed pre-registration seats

            // Concept truths — the strategically correct moves.
            this.TRUE_JOB = `frontdoor`;       // brand-building front door / portfolio play
            this.TRUE_MOAT = `brand`;          // live accredited faculty + cohort + stackable
            this.TRUE_FORMAT = `hybrid`;       // scalable AND differentiated
            this.TRUE_PRICE = 5900;            // modelled midpoint clears both targets
            this.TRUE_MODE = `partner`;        // local partner: reach + self-funding
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    enroll: 0,                 // confirmed seats toward the 300 target
                    contrib: 0,                // USD M contribution after 28% overhead
                    diff: 30,                  // differentiation / projected NPS (0-100)
                    reach: 0,                  // Singapore / Shanghai market reach (0-100)
                    cacUsed: 0,                // USD M of marketing / CAC committed
                    costPerSeat: 0,            // fully-loaded delivery cost per seat (USD)
                    cohortCap: 0,              // seats per cohort implied by the format
                    price: 0,                  // committed Mini-MBA price (USD)
                    pricedAtRival: false,
                    boughtWithDiscount: false,
                    goldPlated: false,
                    unfundedExpansion: false,
                    oneNumberScorecard: false,
                    enrollHistory: [0],
                    contribHistory: [0],
                    diffHistory: [30],
                    reachHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win both targets.
                state.decisions = {
                    job: `replace`,
                    moat: `content`,
                    focus: 50,
                    format: `online`,
                    modules: 6,
                    credential: `badge`,
                    diffSpend: 0,
                    price: 2200,
                    corp: 40,
                    discount: 20,
                    cac: 0.2,
                    mode: `export`,
                    funding: `hope`,
                    scorecard: `enroll`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const jb = document.getElementById(`jobInput`);
                const mo = document.getElementById(`moatInput`);
                const fo = document.getElementById(`focusInput`);
                if (jb) decisions.job = jb.value;
                if (mo) decisions.moat = mo.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const fm = document.getElementById(`formatInput`);
                const md = document.getElementById(`modulesInput`);
                const cr = document.getElementById(`credentialInput`);
                const ds = document.getElementById(`diffSpendInput`);
                if (fm) decisions.format = fm.value;
                if (md) decisions.modules = parseInt(md.value, 10);
                if (cr) decisions.credential = cr.value;
                if (ds) decisions.diffSpend = parseFloat(ds.value);
                if (!Number.isFinite(decisions.modules) || decisions.modules < 4 || decisions.modules > 12) {
                    warn(`warn_modules_range`); return false;
                }
                if (!Number.isFinite(decisions.diffSpend) || decisions.diffSpend < 0) {
                    warn(`warn_diffspend_value`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`priceInput`);
                const co = document.getElementById(`corpInput`);
                const di = document.getElementById(`discountInput`);
                const ca = document.getElementById(`cacInput`);
                if (pr) decisions.price = parseInt(pr.value, 10);
                if (co) decisions.corp = parseInt(co.value, 10);
                if (di) decisions.discount = parseInt(di.value, 10);
                if (ca) decisions.cac = parseFloat(ca.value);
                if (!Number.isFinite(decisions.price) || decisions.price <= 0) {
                    warn(`warn_price_value`); return false;
                }
                if (!Number.isFinite(decisions.corp) || decisions.corp < 0 || decisions.corp > 100) {
                    warn(`warn_corp_range`); return false;
                }
                if (!Number.isFinite(decisions.discount) || decisions.discount < 0 || decisions.discount > 50) {
                    warn(`warn_discount_range`); return false;
                }
            } else if (round === 4) {
                const mo = document.getElementById(`modeInput`);
                const fu = document.getElementById(`fundingInput`);
                const sc = document.getElementById(`scorecardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (mo) decisions.mode = mo.value;
                if (fu) decisions.funding = fu.value;
                if (sc) decisions.scorecard = sc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let enrollDelta = 0, contribDelta = 0, diffDelta = 0, reachDelta = 0, cacSpend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the portfolio & the threat (Common Error 5: standalone, one-number thinking).
                switch (d.job) {
                    case `frontdoor`: diffDelta += 12; reachDelta += 6; coachKey = `coach_r1_frontdoor`; break;
                    case `replace`: diffDelta += 2; coachKey = `coach_r1_replace`; break;
                    case `match`: diffDelta -= 10; ds.pricedAtRival = false; coachKey = `coach_r1_match`; break;
                    case `premium`: diffDelta += 6; reachDelta -= 6; coachKey = `coach_r1_premium`; break;
                }

                // Name the single advantage LearnLadder structurally cannot copy (Key Concept: differentiation).
                switch (d.moat) {
                    case `brand`: diffDelta += 12; if (d.job === `frontdoor`) coachKey = `coach_r1_sharp`; break;
                    case `content`: diffDelta -= 4; coachKey = `coach_r1_content`; break;
                    case `price`: diffDelta -= 10; coachKey = `coach_r1_pricemoat`; break;
                    case `none`: diffDelta -= 12; coachKey = `coach_r1_nomoat`; break;
                }

                if (d.focus >= 60) { diffDelta += 6; }
                else if (d.focus <= 25) { diffDelta -= 6; coachKey = `coach_r1_unfocused`; }

                summaryKey = (d.job === `frontdoor` && d.moat === `brand`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the curriculum & format — fixes cost-per-seat, cohort scale & differentiation.
                // Format sets the fully-loaded cost-per-seat and the per-cohort cap (scalability).
                // Exec-ed has high fixed design cost and LOW marginal delivery cost; these are the
                // fully-loaded delivery costs per seat (faculty stipend + materials + ops, ex-overhead).
                if (d.format === `online`) {
                    ds.costPerSeat = 700; ds.cohortCap = 1000;
                    diffDelta -= 8; reachDelta += 4; coachKey = `coach_r2_online`;
                } else if (d.format === `hybrid`) {
                    ds.costPerSeat = 650; ds.cohortCap = 60;
                    diffDelta += 12; reachDelta += 8; coachKey = `coach_r2_hybrid`;
                } else { // inperson — gold-plated, low scale (Common Error 3).
                    ds.costPerSeat = 3500; ds.cohortCap = 25;
                    diffDelta += 16; reachDelta -= 6; ds.goldPlated = true; coachKey = `coach_r2_inperson`;
                }

                // Module count: 6-10 is the sweet spot; too few = thin, too many = cost with little WTP.
                if (d.modules >= 6 && d.modules <= 10) {
                    diffDelta += 4;
                } else if (d.modules < 6) {
                    diffDelta -= 6; coachKey = `coach_r2_thin`;
                } else {
                    ds.costPerSeat += (d.modules - 10) * 150; diffDelta += 1; coachKey = `coach_r2_bloated`;
                }

                // Credential changes willingness-to-pay and the degree-feeder role.
                switch (d.credential) {
                    case `stackable`: diffDelta += 10; reachDelta += 2; break;
                    case `certificate`: diffDelta += 4; break;
                    case `badge`: diffDelta -= 8; coachKey = `coach_r2_badge`; break;
                }

                // Non-commodity design spend (capstone, employer co-design, alumni access).
                cacSpend += d.diffSpend;
                if (d.diffSpend >= 0.6) { diffDelta += 12; }
                else if (d.diffSpend >= 0.3) { diffDelta += 6; }
                else { diffDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_nodiff`; }

                summaryKey = (d.format === `hybrid` && d.credential !== `badge` && d.diffSpend >= 0.3) ? `sum_r2_good` :
                             (d.format === `inperson` ? `sum_r2_gold` : `sum_r2_weak`);
            } else if (round === 3) {
                // Price under the enrollment constraint — the heart of the simulation.
                ds.price = d.price;
                const price = d.price;
                const cost = ds.costPerSeat > 0 ? ds.costPerSeat : 1150;  // fallback if R2 skipped (hybrid)
                const cap = ds.cohortCap > 0 ? ds.cohortCap : 60;

                // Demand model: lower price draws more seats, but the differentiation built in R1/R2
                // raises willingness-to-pay so a differentiated program holds volume at a higher price.
                // Base demand at the modelled midpoint, scaled by price and by differentiation.
                const diffFactor = 0.55 + (ds.diff / 100) * 1.35;         // 0.55 .. 1.90
                // Price elasticity: relative to the USD 5,900 modelled midpoint.
                let priceFactor;
                if (price <= 2200) priceFactor = 1.55;
                else if (price <= 3500) priceFactor = 1.30;
                else if (price <= 5900) priceFactor = 1.15;
                else priceFactor = 0.70;                                   // 8,500 near legacy: thin volume

                // CAC fills the funnel in six weeks.
                cacSpend += d.cac;
                let cacFactor = 1.0;
                if (d.cac >= 0.9) cacFactor = 1.25;
                else if (d.cac >= 0.5) cacFactor = 1.10;
                else cacFactor = 0.85;

                let seats = Math.round(this.PRESPRING * priceFactor * diffFactor * cacFactor);

                // Gold-plated low-scale design simply cannot physically reach 300 in one cycle.
                if (cap < 40) {
                    seats = Math.min(seats, cap);                         // one cohort this cycle
                }
                ds.enroll = Math.min(2000, seats);
                enrollDelta = ds.enroll;

                // Contribution: revenue per seat after the corporate discount, minus cost, after overhead.
                const corpShare = d.corp / 100;
                const indivSeats = ds.enroll * (1 - corpShare);
                const corpSeats = ds.enroll * corpShare;
                const corpPrice = price * (1 - d.discount / 100);
                const grossRev = indivSeats * price + corpSeats * corpPrice;
                const afterOverhead = grossRev * (1 - this.OVERHEAD);
                const totalCost = ds.enroll * cost;
                const contribUSD = afterOverhead - totalCost;            // USD
                ds.contrib = Math.round((contribUSD / 1e6) * 100) / 100; // USD M
                contribDelta = ds.contrib;

                // Flags for the debrief (drive coach + end summary).
                if (price <= 2200) { ds.pricedAtRival = true; }
                if (d.discount >= 40 && corpShare >= 0.4) { ds.boughtWithDiscount = true; }

                // Coach selection: the documented errors fire here.
                if (price <= 2200) {
                    coachKey = `coach_r3_match`;                          // Common Error 1: margin trap
                } else if (ds.boughtWithDiscount) {
                    coachKey = `coach_r3_discount`;                       // Common Error 2: buy seats with margin
                } else if (cap < 40 && ds.enroll < this.TARGET_ENROLL) {
                    coachKey = `coach_r3_cantscale`;                      // Common Error 3 surfaces in pricing
                } else if (ds.enroll >= this.TARGET_ENROLL && ds.contrib >= this.TARGET_CONTRIB) {
                    coachKey = `coach_r3_bothtargets`;
                } else if (ds.enroll >= this.TARGET_ENROLL) {
                    coachKey = `coach_r3_enrollonly`;
                } else if (ds.contrib >= this.TARGET_CONTRIB) {
                    coachKey = `coach_r3_contribonly`;
                } else {
                    coachKey = `coach_r3_neither`;
                }

                const bothHit = (ds.enroll >= this.TARGET_ENROLL && ds.contrib >= this.TARGET_CONTRIB);
                summaryKey = bothHit ? `sum_r3_good` :
                             (ds.pricedAtRival ? `sum_r3_match` :
                             (ds.boughtWithDiscount ? `sum_r3_discount` : `sum_r3_weak`));
            } else if (round === 4) {
                // Choose the expansion mode (self-funding) & set a balanced scorecard.
                const contribOK = ds.contrib >= 0.8;   // does the program actually throw off margin to fund Asia?
                switch (d.mode) {
                    case `partner`: reachDelta += 25; diffDelta += 2; coachKey = `coach_r4_partner`; break;
                    case `export`: reachDelta += 12; diffDelta -= 6; coachKey = `coach_r4_export`; break;
                    case `flyin`: reachDelta += 16; diffDelta += 6;
                        if (!contribOK || ds.price < 8000) { reachDelta -= 10; coachKey = `coach_r4_flyin_unfunded`; }
                        else { coachKey = `coach_r4_flyin`; }
                        break;
                    case `license`: reachDelta += 18; diffDelta -= 8; coachKey = `coach_r4_license`; break;
                }

                // Funding logic — an expansion mode is only real if it self-funds from contribution.
                switch (d.funding) {
                    case `contribution`:
                        if (contribOK) { reachDelta += 6; diffDelta += 2; }
                        else { reachDelta -= 8; ds.unfundedExpansion = true; coachKey = `coach_r4_nocontrib`; }
                        break;
                    case `hope`: reachDelta -= 12; ds.unfundedExpansion = true; coachKey = `coach_r4_hope`; break;
                    case `margin`: reachDelta -= 6; contribDelta -= 0.2; ds.unfundedExpansion = true; coachKey = `coach_r4_cutprice`; break;
                }

                // Scorecard — one-number measurement (Common Error 5) tanks word-of-mouth & reach evidence.
                switch (d.scorecard) {
                    case `balanced`: diffDelta += 8; reachDelta += 6; break;
                    case `enrollrev`: diffDelta += 2; reachDelta -= 4; coachKey = `coach_r4_enrollrev`; break;
                    case `enroll`: diffDelta -= 8; reachDelta -= 8; ds.oneNumberScorecard = true; coachKey = `coach_r4_enrollonly`; break;
                }

                if (d.conviction >= 60) { diffDelta += 4; reachDelta += 3; }
                else if (d.conviction <= 25) { diffDelta -= 4; reachDelta -= 3; }

                summaryKey = (d.mode === `partner` && d.funding === `contribution` && d.scorecard === `balanced`) ? `sum_r4_good` :
                             (ds.unfundedExpansion ? `sum_r4_unfunded` :
                             (ds.oneNumberScorecard ? `sum_r4_onenumber` : `sum_r4_weak`));
            }

            // Resource accounting: marketing / design spend (CAC) is metered across rounds.
            ds.cacUsed = Math.round((ds.cacUsed + cacSpend) * 100) / 100;

            // Apply deltas. enroll & contrib are set directly in R3; carry them forward otherwise.
            if (round !== 3) {
                // enroll/contrib don't change outside the pricing round.
            }
            ds.diff = Math.max(0, Math.min(100, Math.round(ds.diff + diffDelta)));
            ds.reach = Math.max(0, Math.min(100, Math.round(ds.reach + reachDelta)));
            if (round === 4 && contribDelta < 0) {
                ds.contrib = Math.round((ds.contrib + contribDelta) * 100) / 100;
            }

            ds.enrollHistory.push(ds.enroll);
            ds.contribHistory.push(Math.round(ds.contrib * 100) / 100);
            ds.diffHistory.push(ds.diff);
            ds.reachHistory.push(ds.reach);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where results_utils.php reads it (per-period + final):
            //   express_resolveDomainScore -> domainState.performance.overallScore (then top-level score)
            //   express_extractHistory     -> domainState.performance.overallScore / results.score
            const _score = this._composite(ds);
            ds.score = _score;
            if (!ds.performance || typeof ds.performance !== `object`) { ds.performance = {}; }
            ds.performance.overallScore = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                enroll: ds.enroll,
                contrib: ds.contrib,
                diff: ds.diff,
                diffDelta: Math.round(diffDelta),
                reach: ds.reach,
                reachDelta: Math.round(reachDelta),
                cacUsed: ds.cacUsed,
                price: ds.price,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoneyM(v) {
            // USD millions, en notation: $1.50M ; es notation: 1,50 M$ (comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} M$`;
            }
            return `${sign}$${abs.toFixed(2)}M`;
        }

        _fmtPrice(v) {
            // USD whole-dollar tuition, locale grouping. en: $5,900 ; es: 5.900 $.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) || 0);
            if (lang === `es`) {
                return n.toLocaleString(`es-ES`) + ` $`;
            }
            return `$` + n.toLocaleString(`en-US`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`enrollDisplay`, `domainState.enroll`, (v) => {
                const card = document.querySelector(`.minimbasim-card-enroll`);
                if (card) {
                    card.classList.toggle(`minimbasim-enroll-hit`, Number(v) >= self.TARGET_ENROLL);
                    card.classList.toggle(`minimbasim-enroll-miss`, Number(v) > 0 && Number(v) < self.TARGET_ENROLL);
                }
                return Math.round(Number(v)) + ` / ` + self.TARGET_ENROLL;
            });
            uiManager.bind(`contribDisplay`, `domainState.contrib`, (v) => {
                const card = document.querySelector(`.minimbasim-card-contrib`);
                if (card) {
                    card.classList.toggle(`minimbasim-contrib-positive`, Number(v) >= self.TARGET_CONTRIB);
                    card.classList.toggle(`minimbasim-contrib-negative`, Number(v) < 0);
                    card.classList.toggle(`minimbasim-contrib-hit`, Number(v) >= self.TARGET_CONTRIB);
                }
                return self._fmtMoneyM(Number(v));
            });
            uiManager.bind(`diffDisplay`, `domainState.diff`, (v) => Math.round(Number(v)));
            uiManager.bind(`reachDisplay`, `domainState.reach`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.cacUsed`, (v) => self._fmtMoneyM(Number(v)));

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Corporate-share slider readout.
            const co = document.getElementById(`corpInput`);
            const coReadout = document.getElementById(`corpReadout`);
            if (co && coReadout) {
                coReadout.textContent = co.value;
                co.addEventListener(`input`, function() { coReadout.textContent = co.value; });
            }

            // Corporate-discount slider readout.
            const di = document.getElementById(`discountInput`);
            const diReadout = document.getElementById(`discountReadout`);
            if (di && diReadout) {
                diReadout.textContent = di.value;
                di.addEventListener(`input`, function() { diReadout.textContent = di.value; });
            }
        }

