        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.diffHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                minimbaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.enrollHistory },
                        { data: ds.diffHistory },
                        { data: ds.reachHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0: verbatim v1.0.0 formula, extracted so calculateResults can persist it every period.
            const enroll = Math.round(ds.enroll);
            const contrib = Math.round(ds.contrib * 100) / 100;
            const diff = Math.round(ds.diff);
            const reach = Math.round(ds.reach);
            const enrollScore = Math.max(0, Math.min(100, (enroll / this.TARGET_ENROLL) * 100));
            const contribScore = Math.max(0, Math.min(100, (contrib / this.TARGET_CONTRIB) * 100));
            return Math.round(enrollScore * 0.28 + contribScore * 0.32 + diff * 0.22 + reach * 0.18);
        }

        formatCompletionMessage(summary) {
            // v1.1.0: localized debrief. Without this override the engine renders a generic
            // "You completed N periods" and discards the score, tier, targets and insights.
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            if (!summary || typeof summary.composite === `undefined`) {
                return `<div class="mmba-cm"><div class="mmba-cm-tier">${t(`grade_opm`)}</div></div>`;
            }
            const money = (v) => this._fmtMoneyM(Number(v));
            const tier = summary.performance || t(summary.performanceKey || `grade_opm`);
            const eHit = !!summary.enrollHit, cHit = !!summary.contribHit;
            const badge = (hit) => `<span class="mmba-cm-badge ${hit ? `is-met` : `is-missed`}">${hit ? t(`cm_met`) : t(`cm_missed`)}</span>`;
            const lis = (summary.insights || []).map((s) => `<li>${s}</li>`).join(``);
            return `
                <div class="mmba-cm">
                    <div class="mmba-cm-head">
                        <div class="mmba-cm-scorebox">
                            <div class="mmba-cm-score">${summary.composite}<span class="mmba-cm-score-max">/100</span></div>
                            <div class="mmba-cm-score-label">${t(`cm_score_label`)}</div>
                        </div>
                        <div class="mmba-cm-tier">${tier}</div>
                    </div>
                    <div class="mmba-cm-targets">
                        <div class="mmba-cm-target ${eHit ? `is-met` : `is-missed`}">
                            <span class="mmba-cm-target-label">${t(`cm_target_enroll`)}</span>
                            <span class="mmba-cm-target-val">${summary.enroll} / ${this.TARGET_ENROLL}</span>
                            ${badge(eHit)}
                        </div>
                        <div class="mmba-cm-target ${cHit ? `is-met` : `is-missed`}">
                            <span class="mmba-cm-target-label">${t(`cm_target_contrib`)}</span>
                            <span class="mmba-cm-target-val">${money(summary.contrib)} / ${money(this.TARGET_CONTRIB)}</span>
                            ${badge(cHit)}
                        </div>
                    </div>
                    <div class="mmba-cm-kpis">
                        <div class="mmba-cm-kpi"><div class="mmba-cm-kpi-v">${summary.enroll}</div><div class="mmba-cm-kpi-l">${t(`cm_kpi_enroll`)}</div></div>
                        <div class="mmba-cm-kpi"><div class="mmba-cm-kpi-v">${money(summary.contrib)}</div><div class="mmba-cm-kpi-l">${t(`cm_kpi_contrib`)}</div></div>
                        <div class="mmba-cm-kpi"><div class="mmba-cm-kpi-v">${summary.diff}</div><div class="mmba-cm-kpi-l">${t(`cm_kpi_diff`)}</div></div>
                        <div class="mmba-cm-kpi"><div class="mmba-cm-kpi-v">${summary.reach}</div><div class="mmba-cm-kpi-l">${t(`cm_kpi_reach`)}</div></div>
                    </div>
                    <div class="mmba-cm-insights">
                        <div class="mmba-cm-insights-title">${t(`cm_insights_title`)}</div>
                        <ul>${lis}</ul>
                    </div>
                </div>
            `;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const enroll = Math.round(ds.enroll);
            const contrib = Math.round(ds.contrib * 100) / 100;
            const diff = Math.round(ds.diff);
            const reach = Math.round(ds.reach);

            const enrollHit = enroll >= this.TARGET_ENROLL;
            const contribHit = contrib >= this.TARGET_CONTRIB;
            const bothTargets = enrollHit && contribHit;

            // Composite: weight both binding targets, plus differentiation and reach.
            // v1.1.0: composite via _composite(ds) — single source of truth, value byte-identical to v1.0.0.
            const composite = this._composite(ds);

            // v1.1.0: tier is now i18n-keyed (was hardcoded English) so it localizes in the history/debrief.
            let performanceKey = `grade_opm`;
            if (bothTargets && diff >= 60 && reach >= 55 && composite >= 78) performanceKey = `grade_growth`;
            else if (bothTargets && reach >= 45) performanceKey = `grade_flagship`;
            else if (ds.pricedAtRival || contrib < 0) performanceKey = `grade_margintrap`;
            else if (ds.goldPlated && !enrollHit) performanceKey = `grade_unscalable`;
            else if (ds.unfundedExpansion) performanceKey = `grade_unfunded`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (bothTargets) insights.push(window.mySimulation.t(`insight_bothtargets`));
            else if (enrollHit && !contribHit) insights.push(window.mySimulation.t(`insight_enrollnotcontrib`));
            else if (!enrollHit && contribHit) insights.push(window.mySimulation.t(`insight_contribnotenroll`));
            else insights.push(window.mySimulation.t(`insight_neither`));

            if (ds.pricedAtRival) insights.push(window.mySimulation.t(`insight_margintrap`));
            if (ds.boughtWithDiscount) insights.push(window.mySimulation.t(`insight_discount`));
            if (ds.goldPlated && !enrollHit) insights.push(window.mySimulation.t(`insight_goldplated`));
            if (ds.unfundedExpansion) insights.push(window.mySimulation.t(`insight_unfunded`));
            if (ds.oneNumberScorecard) insights.push(window.mySimulation.t(`insight_onenumber`));
            if (diff >= 65 && reach >= 55) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                totalPeriods: history.length,
                enroll: enroll,
                contrib: contrib,
                diff: diff,
                reach: reach,
                enrollHit: enrollHit,
                contribHit: contribHit,
                bothTargets: bothTargets,
                composite: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.pricedAtRival) return window.mySimulation.t(`hint_match`);
            if (ds.boughtWithDiscount) return window.mySimulation.t(`hint_discount`);
            if (ds.goldPlated && state.currentPeriod >= 2) return window.mySimulation.t(`hint_goldplated`);
            if (ds.unfundedExpansion) return window.mySimulation.t(`hint_unfunded`);
            if (state.currentPeriod >= 3 && ds.contrib < this.TARGET_CONTRIB && ds.enroll >= this.TARGET_ENROLL) return window.mySimulation.t(`hint_contrib`);
            if (state.currentPeriod >= 3 && ds.enroll < this.TARGET_ENROLL) return window.mySimulation.t(`hint_enroll`);
            if (ds.diff >= 65 && ds.reach >= 50 && ds.contrib >= this.TARGET_CONTRIB) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.enroll`, label: `Enroll`, i18nKey: `col_enroll`, formatter: (v) => Math.round(v) },
                { key: `results.contrib`, label: `Contribution`, i18nKey: `col_contrib`, formatter: (v) => self._fmtMoneyM(Number(v)) },
                { key: `results.diff`, label: `Diff/NPS`, i18nKey: `col_diff`, formatter: (v) => Math.round(v) },
                { key: `results.reach`, label: `Reach`, i18nKey: `col_reach`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
